package ledger.record;

/** Why a posting exists. */
public enum PostingType {
    /** A CREDIT event: money in. */
    EXTERNAL_CREDIT,
    /** A DEBIT event: money out. */
    EXTERNAL_DEBIT,
    /** The captured amount of a settled authorization. */
    SETTLEMENT_DEBIT,
    /** Generated by the engine at a day close or when a closed day is re-checked. */
    OVERDRAFT_FEE,
    /** Equal and opposite to an earlier CREDIT or DEBIT posting; the original stays in the log. */
    REVERSAL,
    /** One child of an instalment credit; the children sum exactly to the total. */
    INSTALMENT_CREDIT
}
